// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Cloud copy of car rows as gzip JSON-lines
// Flo: build JSONL from the tables (raw phone never leaves the machine, only its hash) > hash it > skip when the same as last time > gzip > put > get back and compare > remember the hash
// I/O: open Db + object store + clock (caller) > Sres; the store key is overwritten each time, so cloud space stays one snapshot; failures leave the old snapshot and the flag untouched
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("sy-clou-stor.zig"); const file = @import("st-stor-file.zig"); const fail = @import("ru-fail-over.zig");
pub const KEYS = [_][]const u8{ "cars/rows.jsonl.gz", "cars/price.jsonl.gz", "cars/roll.jsonl.gz" };
const FLAG = [_][]const u8{ "carz_snap_a", "carz_snap_b", "carz_snap_c" };
pub const Sres = struct { sent: u8 = 0, same: u8 = 0 };
const Rowz = struct { urlz: []const u8, site: []const u8, lidz: []const u8, clsz: []const u8, titl: []const u8, make: []const u8, modl: []const u8, trim: []const u8, year: i64, body: []const u8, seat: i64, door: i64, orig: []const u8, cond: []const u8, powr: []const u8, fuel: []const u8, engn: []const u8, gear: []const u8, driv: []const u8, colx: []const u8, coli: []const u8, kmzz: i64, owns: i64, pric: i64, prov: []const u8, dist: []const u8, post: i64, sell: []const u8, shop: []const u8, phsh: []const u8, text: []const u8, xtra: []const u8, pver: i64, fors: i64, lasz: i64, stat: i64, gone: i64, grsn: []const u8, clus: []const u8 };
fn lineAddz(aren: std.mem.Allocator, outp: *std.ArrayList(u8), valu: anytype) !void { const txtz = try std.json.Stringify.valueAlloc(aren, valu, .{}); try outp.appendSlice(aren, txtz); try outp.append(aren, '\n'); }
pub fn rowsBuil(aren: std.mem.Allocator, dbzz: *sqli.Dbzz) ![]u8 { var outp: std.ArrayList(u8) = .empty; var stmt = try dbzz.prep("SELECT urlz,site,lidz,clsz,titl,make,modl,trim,year,body,seat,door,orig,cond,powr,fuel,engn,gear,driv,colx,coli,kmzz,owns,pric,prov,dist,post,sell,shop,phsh,text,xtra,pver,fors,lasz,stat,gone,grsn,clus FROM carz ORDER BY urlz;"); defer stmt.fini(); while (try stmt.step()) { const rowz: Rowz = .{ .urlz = stmt.colzText(0), .site = stmt.colzText(1), .lidz = stmt.colzText(2), .clsz = stmt.colzText(3), .titl = stmt.colzText(4), .make = stmt.colzText(5), .modl = stmt.colzText(6), .trim = stmt.colzText(7), .year = stmt.colzIntz(8), .body = stmt.colzText(9), .seat = stmt.colzIntz(10), .door = stmt.colzIntz(11), .orig = stmt.colzText(12), .cond = stmt.colzText(13), .powr = stmt.colzText(14), .fuel = stmt.colzText(15), .engn = stmt.colzText(16), .gear = stmt.colzText(17), .driv = stmt.colzText(18), .colx = stmt.colzText(19), .coli = stmt.colzText(20), .kmzz = stmt.colzIntz(21), .owns = stmt.colzIntz(22), .pric = stmt.colzIntz(23), .prov = stmt.colzText(24), .dist = stmt.colzText(25), .post = stmt.colzIntz(26), .sell = stmt.colzText(27), .shop = stmt.colzText(28), .phsh = stmt.colzText(29), .text = stmt.colzText(30), .xtra = stmt.colzText(31), .pver = stmt.colzIntz(32), .fors = stmt.colzIntz(33), .lasz = stmt.colzIntz(34), .stat = stmt.colzIntz(35), .gone = stmt.colzIntz(36), .grsn = stmt.colzText(37), .clus = stmt.colzText(38) }; try lineAddz(aren, &outp, rowz); } return outp.toOwnedSlice(aren); }
pub fn pricBuil(aren: std.mem.Allocator, dbzz: *sqli.Dbzz) ![]u8 { var outp: std.ArrayList(u8) = .empty; var stmt = try dbzz.prep("SELECT urlz,timz,pric FROM carp ORDER BY urlz,timz;"); defer stmt.fini(); while (try stmt.step()) { try lineAddz(aren, &outp, .{ .urlz = stmt.colzText(0), .timz = stmt.colzIntz(1), .pric = stmt.colzIntz(2) }); } return outp.toOwnedSlice(aren); }
pub fn rollBuil(aren: std.mem.Allocator, dbzz: *sqli.Dbzz) ![]u8 { var outp: std.ArrayList(u8) = .empty; var stmt = try dbzz.prep("SELECT wkzz,make,modl,year,powr,cond,cont,pmed,pq25,pq75,kmed,domm FROM carr ORDER BY wkzz,make,modl,year,powr,cond;"); defer stmt.fini(); while (try stmt.step()) { try lineAddz(aren, &outp, .{ .wkzz = stmt.colzIntz(0), .make = stmt.colzText(1), .modl = stmt.colzText(2), .year = stmt.colzIntz(3), .powr = stmt.colzText(4), .cond = stmt.colzText(5), .cont = stmt.colzIntz(6), .pmed = stmt.colzIntz(7), .pq25 = stmt.colzIntz(8), .pq75 = stmt.colzIntz(9), .kmed = stmt.colzIntz(10), .domm = stmt.colzIntz(11) }); } return outp.toOwnedSlice(aren); }
fn pushOnez(dbzz: *sqli.Dbzz, stoz: stor.Stor, iozz: std.Io, aren: std.mem.Allocator, key2: []const u8, flag: []const u8, body: []const u8) !bool { const codz: i64 = @bitCast(std.hash.Wyhash.hash(0xca25, body)); if (body.len == 0) return false; if ((try fail.flagGetz(dbzz, flag)) == codz) return false; const gzzz = try file.gzipPack(aren, body); try stoz.put(stoz.ctx2, aren, iozz, key2, gzzz); const back = try stoz.get(stoz.ctx2, aren, iozz, key2); const open = file.gzipOpen(aren, back, body.len + 1024) catch return error.Fail; if (!std.mem.eql(u8, open, body)) return error.Fail; try fail.flagSetz(dbzz, flag, codz); return true; }
pub fn snapRunz(dbzz: *sqli.Dbzz, stoz: stor.Stor, iozz: std.Io, aren: std.mem.Allocator) !Sres { var rslt: Sres = .{}; const bodz = [_][]u8{ try rowsBuil(aren, dbzz), try pricBuil(aren, dbzz), try rollBuil(aren, dbzz) }; for (bodz, 0..) |body, indx| { if (try pushOnez(dbzz, stoz, iozz, aren, KEYS[indx], FLAG[indx], body)) rslt.sent += 1 else rslt.same += 1; } return rslt; }
